/**
 * @summary Upload a media file
 */
export const getUploadMediaUrl = () => {
  return `/api/media`;
};

export const uploadMedia = async (
  uploadMediaBody: UploadMediaBody,
  options?: RequestInit,
): Promise<MediaItem> => {
  const formData = new FormData();
  formData.append(`file`, uploadMediaBody.file);
  formData.append(`title`, uploadMediaBody.title);
  if (uploadMediaBody.artist !== undefined) {
    formData.append(`artist`, uploadMediaBody.artist);
  }
  formData.append(`type`, uploadMediaBody.type);
  formData.append(`clientId`, uploadMediaBody.clientId.toString());
  if (uploadMediaBody.gain !== undefined) {
    formData.append(`gain`, uploadMediaBody.gain.toString());
  }

  return customFetch<MediaItem>(getUploadMediaUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

