/**
 * @summary Log a completed media playback
 */
export const getLogPlaybackUrl = () => {
  return `/api/playback/log`;
};

export const logPlayback = async (
  logPlaybackBody: LogPlaybackBody,
  options?: RequestInit,
): Promise<SuccessResponse> => {
  return customFetch<SuccessResponse>(getLogPlaybackUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(logPlaybackBody),
  });
};

export const getLogPlaybackMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof logPlayback>>,
    TError,
    { data: BodyType<LogPlaybackBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof logPlayback>>,
  TError,
  { data: BodyType<LogPlaybackBody> },
  TContext
> => {
  const mutationKey = ["logPlayback"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof logPlayback>>,
    { data: BodyType<LogPlaybackBody> }
  > = (props) => {
    const { data } = props ?? {};

    return logPlayback(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type LogPlaybackMutationResult = NonNullable<
  Awaited<ReturnType<typeof logPlayback>>
>;
export type LogPlaybackMutationBody = BodyType<LogPlaybackBody>;
export type LogPlaybackMutationError = ErrorType<unknown>;

